import sys

def decode_brute(s):
    count = []
    res = ['']
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            count.append(num)
            res.append('')
            num = 0
        elif ch == ']':
            k = count.pop()
            cur = res.pop()
            res[-1] += cur * k
        else:
            res[-1] += ch
    return res[0]

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip()
    print(decode_brute(s))

import sys

def decode_opt(s):
    i = 0
    def parse():
        nonlocal i
        res = []
        num = 0
        while i < len(s):
            ch = s[i]
            if ch.isdigit():
                num = num * 10 + int(ch)
                i += 1
            elif ch == '[':
                i += 1
                inner = parse()
                res.append(inner * num)
                num = 0
            elif ch == ']':
                i += 1
                return ''.join(res)
            else:
                res.append(ch)
                i += 1
        return ''.join(res)
    return parse()

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip()
    print(decode_opt(s))

import sys

def decode_best(s: str) -> str:
    count_stack = []
    res_stack = ['']
    num = 0
    for ch in s:
        if ch.isdigit():
            num = num * 10 + int(ch)
        elif ch == '[':
            count_stack.append(num)
            res_stack.append('')
            num = 0
        elif ch == ']':
            k = count_stack.pop()
            cur = res_stack.pop()
            res_stack[-1] += cur * k
        else:
            res_stack[-1] += ch
    return res_stack[0]

if __name__ == '__main__':
    s = sys.stdin.readline().rstrip('\n')
    print(decode_best(s))
